/*
  與「文章列表」有關的樣式
*/
@keyframes pageloading {
  0% {
    content: "LOADING";
  }
  25% {
    content: "LOADING.";
  }
  50% {
    content: "LOADING..";
  }
  75% {
    content: "LOADING...";
  }
  100% {
    content: "LOADING...";
  }
}
.blogList {
  margin-bottom: 0.5rem;
}
.blogList .card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.blogList h5, .blogList .h5 {
  margin: 0;
}
.blogList > ul {
  position: relative;
}
.blogList li {
  list-style: none;
}
.blogList .list-group-item > div:not(:first-child) {
  text-align: center;
}
.blogList [data-blog-id] > div:not(:first-child) {
  font-size: 0.8rem;
}
.blogList .filler + div {
  visibility: hidden;
}
.blogList .filler::after {
  content: " ";
}
.blogList .pageLoading {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 300;
  background: rgba(255, 255, 255, 0.5);
}
.blogList .pageLoading > h1, .blogList .pageLoading > .h1 {
  width: 100%;
  margin: 0;
}
.blogList .pageLoading > h1::before, .blogList .pageLoading > .h1::before {
  display: block;
  text-align: center;
  content: "loading";
  animation: pageloading 1.5s infinite step-end;
}

h5, .h5 {
  margin-bottom: 0;
}

img {
  border-radius: 50% 50%;
  border-color: rgba(0, 0, 0, 0.1);
  border-width: 1px;
  border-style: solid;
  font-size: 999;
}

#user-info,
#blog-info,
#follow-info {
  margin-bottom: 1rem;
}

/* user info */
.avatar-box {
  padding: 1rem;
}

.list-group-item > div:nth-child(3) {
  text-align: right !important;
  min-width: 100px;
}

[data-blog-id] > div:first-child {
  flex-shrink: 1;
}
[data-blog-id] > div:nth-child(3) {
  z-index: 200;
}

/* follow info */
#follow-info .card {
  margin-bottom: 1rem;
}
#follow-info .card .card-body:hover {
  background-color: rgba(219, 159, 159, 0.2);
}
#follow-info .card .card-body .betterscroll-outer {
  padding: 0;
  overflow: hidden;
  background-color: rgba(255, 255, 255, 0.3);
  width: 100%;
}
#follow-info .card .card-body .betterscroll-outer > ul {
  display: inline-flex;
}
#follow-info .card .card-body .betterscroll-outer > ul li {
  width: 6rem;
  background: rgba(255, 255, 255, 0.1);
  border: none;
  flex-shrink: 0;
  margin-right: 0.25rem;
  padding: 0.25rem;
  text-align: center;
  pointer-events: auto !important;
}
#follow-info .card .card-body .betterscroll-outer > ul li:hover {
  background-color: rgba(219, 159, 159, 0.5);
}
#follow-info .card .card-body .betterscroll-outer > ul li:last-child {
  margin-right: 0;
}
#follow-info .card .card-body .betterscroll-outer > ul li a {
  text-decoration: none;
}
#follow-info .card .card-body .betterscroll-outer div {
  width: 100%;
  text-align: center;
}

@media (max-width: 575.9px) {
  #user-info .avatar-box {
    flex-grow: 0;
    flex-shrink: 0;
    flex-basis: auto;
    max-width: 12rem;
    margin: 0 auto;
  }
  #user-info .card-title,
  #user-info hr {
    display: none;
  }
  #user-info .card-body {
    text-align: center;
  }
